    justify-content: center;
    height: 100%;
    color: #8e9297;
    font-size: 1.1rem;
}

/* Message List */
.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.loading-indicator {
    text-align: center;
    color: #8e9297;
    padding: 0.5rem;
    font-size: 0.85rem;
}

/* Message Bubble */
.message-bubble {
    position: relative;
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    transition: background-color 0.1s;
}

.message-bubble:hover {
    background-color: #32353b;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 0.2rem;
}

.message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9rem;
}

.message-time {
    font-size: 0.7rem;
    color: #72767d;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.4;
    word-wrap: break-word;
}

/* Reactions */
.message-reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.25rem;
    margin-top: 0.4rem;
}

.reaction-badge {
    background-color: #2f3136;
    border: 1px solid #40444b;
    border-radius: 4px;
    padding: 0.15rem 0.4rem;
    font-size: 0.8rem;
    cursor: pointer;
    color: #dcddde;
    transition: background-color 0.15s;
}

.reaction-badge:hover {
    background-color: #40444b;
    border-color: #5865f2;
}

/* Thread link */
.thread-link {
    background: none;
    border: none;
    color: #5865f2;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 0.2rem 0;
    margin-top: 0.25rem;
    font-weight: 500;
}

.thread-link:hover {
    text-decoration: underline;
}

