.message-actions {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.25rem;
    background-color: #2f3136;
    border: 1px solid #40444b;
    border-radius: 4px;
    padding: 0.2rem;
    z-index: 10;
}

.action-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 0.75rem;
    cursor: pointer;
    padding: 0.25rem 0.4rem;
    border-radius: 3px;
    white-space: nowrap;
}

.action-btn:hover {
    background-color: #40444b;
    color: #fff;
}

/* Emoji Picker */
.emoji-picker {
    display: flex;
    gap: 0.25rem;
    background-color: #2f3136;
    border: 1px solid #40444b;
    border-radius: 4px;
    padding: 0.4rem;
    margin-top: 0.25rem;
    width: fit-content;
}

.emoji-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.2rem;
    border-radius: 3px;
    transition: background-color 0.15s;
}

.emoji-btn:hover {
    background-color: #40444b;
}

/* Message Input */
.message-input-area {
    display: flex;
    gap: 0.5rem;
    padding: 0.75rem 1rem;
    border-top: 1px solid #202225;
    flex-shrink: 0;
    align-items: flex-end;
}

.message-textarea {
    flex: 1;
    background-color: #40444b;
    border: none;
    border-radius: 8px;
    color: #dcddde;
    padding: 0.6rem 1rem;
    font-size: 0.9rem;
    resize: none;
    min-height: 2.4rem;
    max-height: 8rem;
    font-family: inherit;
    outline: none;
}

.message-textarea::placeholder {
    color: #72767d;
}

.send-btn {
    background-color: #5865f2;
    color: #fff;
    border: none;
    border-radius: 4px;
    padding: 0.6rem 1rem;
    font-weight: 600;
    font-size: 0.85rem;
    cursor: pointer;
    white-space: nowrap;
    transition: background-color 0.15s;
}

.send-btn:hover:not(:disabled) {
    background-color: #4752c4;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100vh;
    background-color: #2f3136;
    color: #dcddde;
    border-left: 1px solid #202225;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #202225;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

.close-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.2rem 0.5rem;
    border-radius: 3px;
}

.close-btn:hover {
    background-color: #40444b;
    color: #fff;
}

.thread-root-message {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #40444b;
    background-color: #36393f;
    flex-shrink: 0;
}

.thread-root-message .message-author {
    font-size: 0.85rem;
}

.thread-root-message .message-content {
    font-size: 0.85rem;
    margin-top: 0.25rem;
    color: #b9bbbe;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.75rem 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.thread-reply {
    padding: 0.4rem 0;
}

.thread-reply .message-content {
    font-size: 0.85rem;
}

